-- A Data Vault link: insert-only. Each link_order_customer_hk is added once, the first time it is loaded.

with orders as (

    select * from {{ ref('stg_tpch_erp__orders') }}

),

incoming as (

    select
        MD5(COALESCE(UPPER(TRIM(CAST(CAST(orders.o_orderkey AS BIGINT) AS TEXT))), '') || '||' || COALESCE(UPPER(TRIM(CAST(CAST(orders.o_custkey AS BIGINT) AS TEXT))), '')) as link_order_customer_hk,
        MD5(COALESCE(UPPER(TRIM(CAST(CAST(orders.o_custkey AS BIGINT) AS TEXT))), '')) as hub_customer_hk,
        MD5(COALESCE(UPPER(TRIM(CAST(CAST(orders.o_orderkey AS BIGINT) AS TEXT))), '')) as hub_order_hk,
        cast(orders.o_orderkey as BIGINT) as order_number,
        cast(orders.o_custkey as BIGINT) as customer_number,
        cast(orders._ingested_at as TIMESTAMPTZ) as load_date,
        'tpch_erp' as record_source
    from orders
{% if is_incremental() %}
    where cast(orders._ingested_at as TIMESTAMPTZ) > (select coalesce(max(load_date), cast('1900-01-01' as TIMESTAMPTZ)) from {{ this }})
{% endif %}

),

ranked as (

    select
        incoming.*,
        row_number() over (
            partition by incoming.link_order_customer_hk
            order by incoming.load_date asc
        ) as row_in_batch
    from incoming

)
{% if is_incremental() %},

latest as (

    select link_order_customer_hk
    from (
        select
            existing.link_order_customer_hk,
            row_number() over (partition by existing.link_order_customer_hk order by existing.load_date desc) as row_in_table
        from {{ this }} as existing
    ) as versions
    where row_in_table = 1

)
{% endif %}

select
    ranked.link_order_customer_hk,
    ranked.hub_customer_hk,
    ranked.hub_order_hk,
    ranked.order_number,
    ranked.customer_number,
    ranked.load_date,
    ranked.record_source
from ranked
{% if is_incremental() %}
left join latest
    on latest.link_order_customer_hk = ranked.link_order_customer_hk
{% endif %}
where ranked.row_in_batch = 1
{% if is_incremental() %}
    and latest.link_order_customer_hk is null
{% endif %}
